	public AccessPolicy createAccessPolicy( CreateAccessPolicyCommand command )
    throws ProcessingException, IllegalArgumentException {

		AccessPolicy entity = new AccessPolicy();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	AccessPolicyValidator.getInstance().validate( command );    

            entity.setAccessPolicyId( command.getAccessPolicyId() );
            entity.setName( command.getName() );
            entity.setSubjectName( command.getSubjectName() );
            entity.setAccessLevel( command.getAccessLevel() );
            entity.setSubjectType( command.getSubjectType() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of AccessPolicy {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create AccessPolicy - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

