    /**
     * assign Workspace on AccessPolicy
     * @param		command AssignWorkspaceToAccessPolicyCommand	
     * @exception	ProcessingException
     */     
	public void assignWorkspace( AssignWorkspaceToAccessPolicyCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	AccessPolicyValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignWorkspace(command.getAccessPolicyId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AnalyticsWorkspace using id " + command.getAccessPolicyId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

